module.exports = "<ion-header class=\"interior-header\" [attr.dir]=\"language.direction\">\n  \n  <app-page-header titleKey=\"pageHeader.product/products\" fallback=\"/\">\n<div page-actions><button type=\"button\" class=\"icon-button search-toggle\" (click)=\"showSearchbar = !showSearchbar\" [attr.aria-expanded]=\"showSearchbar\" aria-label=\"جستجو در فروشگاه\" title=\"جستجو در فروشگاه\">\r\n        <ion-icon name=\"search-outline\" aria-hidden=\"true\"></ion-icon>\r\n      </button>\n</div>\n\n<div class=\"header-search-bar\" *ngIf=\"showSearchbar\">\r\n    <div class=\"search-input-wrap\">\r\n      <ion-icon name=\"search-outline\" aria-hidden=\"true\"></ion-icon>\r\n      <input type=\"search\" [(ngModel)]=\"queryText\" [placeholder]=\"'search.store' | translate\" (keyup.enter)=\"search()\" autofocus />\r\n      <button type=\"button\" class=\"action-btn primary\" (click)=\"search()\">{{ 'common.search' | translate }}</button>\r\n      <button type=\"button\" class=\"action-btn ghost\" (click)=\"onCancel()\">{{ 'search.cancel' | translate }}</button>\r\n    </div>\r\n  </div>\n  </app-page-header>\n</ion-header>\r\n\r\n<ion-content class=\"category-directory-content\" [attr.dir]=\"language.direction\">\r\n  <div class=\"page-wrapper\">\r\n    <!-- Ambient Backdrop Glows -->\r\n    <div class=\"backdrop-glows\" aria-hidden=\"true\">\r\n      <div class=\"glow-orb glow-purple\"></div>\r\n      <div class=\"glow-orb glow-amber\"></div>\r\n      <div class=\"glow-orb glow-emerald\"></div>\r\n    </div>\r\n\r\n    <!-- Playful Floating Elementary Decor -->\r\n    <span class=\"floating-decor book\" aria-hidden=\"true\">🎒</span>\r\n    <span class=\"floating-decor star\" aria-hidden=\"true\">✦</span>\r\n    <span class=\"floating-decor pencil\" aria-hidden=\"true\">📐</span>\r\n    <span class=\"floating-decor sparkle\" aria-hidden=\"true\">✨</span>\r\n\r\n    <main class=\"category-main\">\r\n      <!-- Hero Section -->\r\n      <section class=\"category-hero\">\r\n        <div class=\"hero-shell\">\r\n          <div class=\"eyebrow-wrap\">\r\n            <span class=\"eyebrow\">\r\n              <span class=\"little-star\">✦</span>\r\n              {{ 'brand.name' | translate }}\r\n            </span>\r\n            <span class=\"hero-chip\">\r\n              <ion-icon name=\"cube-outline\" aria-hidden=\"true\"></ion-icon>\r\n              فروشگاه و ملزومات آموزشی دبستان\r\n            </span>\r\n          </div>\r\n\r\n          <h1>\r\n            دسته‌بندی محصولات و کاربرگ‌های آموزشی:<br />\r\n            <span class=\"highlight\">\r\n              {{ 'catalog.productList' | translate }}\r\n              <svg viewBox=\"0 0 360 20\" aria-hidden=\"true\">\r\n                <path d=\"M5 13Q170 -5 355 10M30 18Q190 2 328 16\" />\r\n              </svg>\r\n            </span>\r\n          </h1>\r\n\r\n          <p class=\"hero-desc\">\r\n            دانلود مستقیم انواع کاربرگ‌های هفتگی، آزمون‌های ماهانه، پیک‌های آدینه، بازی‌های آموزشی، دست‌سازه‌ها و ملزومات کلاسی پایه‌های اول تا ششم دبستان.\r\n          </p>\r\n\r\n          <div class=\"hero-actions\">\r\n            <a routerLink=\"/Product/Search\" class=\"button primary glow\">\r\n              <ion-icon name=\"cube-outline\" aria-hidden=\"true\"></ion-icon>\r\n              <span>{{ 'catalog.allProducts' | translate }}</span>\r\n              <ion-icon name=\"arrow-back-outline\" aria-hidden=\"true\" class=\"action-arrow\"></ion-icon>\r\n            </a>\r\n            <a routerLink=\"/Home/Search\" class=\"button secondary\">\r\n              <ion-icon name=\"school-outline\" aria-hidden=\"true\"></ion-icon>\r\n              <span>{{ 'catalog.allCourses' | translate }}</span>\r\n            </a>\r\n          </div>\r\n\r\n          <!-- Grade Level Filter Pills -->\r\n          <div class=\"grade-pills-row\">\r\n            <span class=\"pills-title\">پایه‌های تحصیلی:</span>\r\n            <a routerLink=\"/Product/Search\" [queryParams]=\"{title: 'پایه اول'}\" class=\"grade-pill active\">\r\n              <span class=\"pill-dot\"></span>\r\n              پایه اول ابتدایی\r\n            </a>\r\n            <a routerLink=\"/Product/Search\" [queryParams]=\"{title: 'پایه دوم'}\" class=\"grade-pill\">پایه دوم دبستان</a>\r\n            <a routerLink=\"/Product/Search\" [queryParams]=\"{title: 'پایه سوم'}\" class=\"grade-pill\">پایه سوم دبستان</a>\r\n            <a routerLink=\"/Product/Search\" [queryParams]=\"{title: 'کاربرگ'}\" class=\"grade-pill\">کاربرگ و پیک آدینه</a>\r\n            <a routerLink=\"/Product/Search\" [queryParams]=\"{title: 'پیش دبستانی'}\" class=\"grade-pill\">پیش‌دبستانی و نوآموزان</a>\r\n          </div>\r\n        </div>\r\n      </section>\r\n\r\n      <!-- Category Cards Grid -->\r\n      <section class=\"category-grid-section\" aria-labelledby=\"grid-title\">\r\n        <div class=\"catalog-heading-row\">\r\n          <div>\r\n            <span class=\"section-kicker\"><span class=\"kicker-sparkle\">✦</span> موضوعات و فایل‌های درسی</span>\r\n            <h2 id=\"grid-title\">انتخاب دسته‌بندی محصولات</h2>\r\n          </div>\r\n          <span class=\"count-chip\" *ngIf=\"categories?.length\">\r\n            {{ categories.length }} دسته‌بندی\r\n          </span>\r\n        </div>\r\n\r\n        <div class=\"categories-cards-grid\" role=\"list\" *ngIf=\"categories?.length\">\r\n          <article class=\"cat-card\" *ngFor=\"let item of categories\" role=\"listitem\">\r\n            <div class=\"cat-card-media\">\r\n              <img [src]=\"item.urlTitle\" [alt]=\"item.title\" loading=\"lazy\" />\r\n              <div class=\"cat-card-overlay\"></div>\r\n              <span class=\"cat-badge\">\r\n                <span class=\"badge-spark\">✦</span>\r\n                کاربرگ و ملزومات\r\n              </span>\r\n            </div>\r\n\r\n            <div class=\"cat-card-body\">\r\n              <h2>{{ item.title }}</h2>\r\n\r\n              <div class=\"cat-card-actions\">\r\n                <a [routerLink]=\"['/Product', 'Search']\" [queryParams]=\"{categoryIds: [item.productCategoryId], page: 1}\" class=\"card-btn products-btn full-width\" [attr.aria-label]=\"('nav.products' | translate) + ' ' + item.title\">\r\n                  <ion-icon name=\"cube-outline\" aria-hidden=\"true\"></ion-icon>\r\n                  <span>مشاهده محصولات این دسته</span>\r\n                  <ion-icon name=\"arrow-back-outline\" aria-hidden=\"true\" class=\"cat-arrow\"></ion-icon>\r\n                </a>\r\n              </div>\r\n            </div>\r\n          </article>\r\n        </div>\r\n\r\n        <!-- Loading State -->\r\n        <div class=\"directory-empty-state\" *ngIf=\"!categoriesLoaded\">\r\n          <ion-spinner name=\"bubbles\" color=\"primary\"></ion-spinner>\r\n          <span>در حال بارگذاری دسته‌بندی محصولات...</span>\r\n        </div>\r\n\r\n        <!-- Empty State -->\r\n        <div class=\"directory-empty-state\" *ngIf=\"categoriesLoaded && !categories.length\">\r\n          <div class=\"empty-icon\">🎒</div>\r\n          <h3>دسته‌بندی‌ای یافت نشد</h3>\r\n          <p>{{ 'catalog.noCategories' | translate }}</p>\r\n        </div>\r\n      </section>\r\n\r\n      <!-- Bottom Supportive Strip -->\r\n      <section class=\"supportive-curriculum-strip\">\r\n        <div class=\"curriculum-item\">\r\n          <div class=\"curr-icon\"><ion-icon name=\"document-attach-outline\"></ion-icon></div>\r\n          <div class=\"curr-text\">\r\n            <b>فایل‌های PDF باکیفیت و آماده چاپ</b>\r\n            <small>صفحه‌آرایی استاندارد A4 بدون هیچ‌گونه تبلیغ و واترمارک مزاحم</small>\r\n          </div>\r\n        </div>\r\n        <div class=\"curriculum-item\">\r\n          <div class=\"curr-icon\"><ion-icon name=\"checkbox-outline\"></ion-icon></div>\r\n          <div class=\"curr-text\">\r\n            <b>منطبق بر بودجه‌بندی رسمی مدارس</b>\r\n            <small>طراحی گام‌به‌گام برای تثبیت یادگیری هفتگی دانش‌آموزان</small>\r\n          </div>\r\n        </div>\r\n        <div class=\"curriculum-item\">\r\n          <div class=\"curr-icon\"><ion-icon name=\"cloud-download-outline\"></ion-icon></div>\r\n          <div class=\"curr-text\">\r\n            <b>دانلود آنی و دسترسی همیشگی</b>\r\n            <small>دسترسی نامحدود و دائمی به تمامی فایل‌های خریداری شده در پنل کاربری</small>\r\n          </div>\r\n        </div>\r\n      </section>\r\n    </main>\r\n  </div>\r\n\r\n  <!-- Go to top floating button -->\r\n  <ion-fab vertical=\"bottom\" horizontal=\"start\" slot=\"fixed\">\r\n    <ion-fab-button color=\"warning\" (click)=\"goTop()\" aria-label=\"رفتن به بالای صفحه\">\r\n      <ion-icon name=\"arrow-up-outline\"></ion-icon>\r\n    </ion-fab-button>\r\n  </ion-fab>\r\n\r\n  <app-footer></app-footer>\r\n</ion-content>\r\n";

